 .macro map map_id:req
 .ifdef \map_id
 .byte \map_id >> 8
 .byte \map_id & 0xFF
 .else
 .error "undefined map (check for typos)"
 .endif
 .endm


 .macro map_script type:req, script:req
 .byte \type
 .4byte \script
 .endm


 .macro map_script_2 var:req, compare:req, script:req
 .2byte \var
 .2byte \compare
 .4byte \script
 .endm


 .macro object_event index:req, gfx:req, x:req, y:req, elevation:req, movement_type:req, x_radius:req, y_radius:req, trainer_type:req, sight_radius_tree_etc:req, script:req, event_flag:req
 .byte \index
 .2byte \gfx
 .byte 0
 .2byte \x, \y
 .byte \elevation
 .byte \movement_type
 .if \x_radius > 15

  .error "movementRangeX has a bitfield of 4 bytes, so values over 15 will overflow. Use a custom script for item balls that should give the player more than 15 items."
 .endif
 .byte ((\y_radius << 4) | \x_radius)
 .space 1
 .2byte \trainer_type
 .2byte \sight_radius_tree_etc
 .4byte \script
 .2byte \event_flag
 .space 2
 inc _num_npcs
 .endm


 .macro clone_event index:req, gfx:req, x:req, y:req, target_local_id:req, target_map_id:req
 .byte \index
 .2byte \gfx
 .byte 255
 .2byte \x, \y
 .byte \target_local_id
 .space 3
 .2byte \target_map_id & 0xFF
 .2byte \target_map_id >> 8
 .space 8
 inc _num_npcs
 .endm


 .macro warp_def x:req, y:req, elevation:req, warpId:req, map_id:req
 .2byte \x, \y
 .byte \elevation
 .byte \warpId
 .byte \map_id & 0xFF
 .byte \map_id >> 8
 inc _num_warps
 .endm


 .macro coord_event x:req, y:req, elevation:req, var:req, varValue:req, script:req
 .2byte \x, \y
 .byte \elevation
 .space 1
 .2byte \var
 .2byte \varValue
 .space 2
 .4byte \script
 inc _num_traps
 .endm


 .macro coord_weather_event x:req, y:req, elevation:req, weather:req
 coord_event \x, \y, \elevation, \weather, 0, NULL
 .endm




 .macro bg_event x:req, y:req, elevation:req, kind:req, arg6:req
 .2byte \x, \y
 .byte \elevation
 .byte \kind
 .space 2
 .4byte \arg6
 inc _num_signs
 .endm


 .macro bg_sign_event x:req, y:req, elevation:req, facing_dir:req, script:req
 bg_event \x, \y, \elevation, \facing_dir, \script
 .endm


 .macro bg_hidden_item_event x:req, y:req, elevation:req, item:req, flag:req, quantity=1, underfoot=FALSE
 .if \flag < 8426
 .error "Hidden Item flag \flag is too small. Must be >= FLAG_HIDDEN_ITEMS_START."
 .endif
 .if \item >= (1 << 12)
 .error "quantity \quantity too large"
 .endif
 .if \quantity >= (1 << 7)
 .error "quantity \quantity too large"
 .endif
 bg_event \x, \y, \elevation, BG_EVENT_HIDDEN_ITEM, \item | (((\flag) - 8426) << 11)| (\quantity << 24) | (\underfoot << 31)
 .endm


 .macro bg_secret_base_event x:req, y:req, elevation:req, secret_base_id:req
 bg_event \x, \y, \elevation, BG_EVENT_SECRET_BASE, \secret_base_id
 .endm


 .macro map_events npcs:req, warps:req, traps:req, signs:req
 .byte _num_npcs, _num_warps, _num_traps, _num_signs
 .4byte \npcs, \warps, \traps, \signs
 reset_map_events
 .endm


 .macro reset_map_events
 .set _num_npcs, 0
 .set _num_warps, 0
 .set _num_traps, 0
 .set _num_signs, 0
 .endm


 reset_map_events




