 .equ GBP, 0xB6
 .equ GBP_TEMPO_BPM, 0x96

.macro gbs_switch channel:req
 .byte KEYSH, 0
 .if \channel == 0
  .byte TEMPO, GBP_TEMPO_BPM/2
 .endif
 .byte GBP, \channel
.endm

.macro note pitch:req, length:req
 .byte (\pitch << 4) | (\length - 1)
.endm

.macro drum_note instrument:req, length:req
 note \instrument, \length
.endm

.macro rest length:req
 note 0, \length
.endm

.macro square_note length:req, volume:req, fade:req, frequency:req
 .byte \length
 .if \fade < 0
  .byte (\volume << 4) | (\fade * -1) | 0b1000
 .else
  .byte (\volume << 4) | (\fade)
 .endif
 .2byte \frequency
.endm

.macro noise_note length:req, volume:req, fade:req, frequency:req
 .byte \length
 .if \fade < 0
  .byte (\volume << 4) | (\fade * -1) | 0b1000
 .else
  .byte (\volume << 4) | (\fade)
 .endif
 .byte \frequency
.endm


 enum_start 0xD0

 enum _octave
.macro octave n:req

    .if 1 <= (\n) && (\n) <= 8
        .byte _octave + 8 - (\n)
    .else
        .byte _octave
    .endif
.endm

 enum_start 0xD8

 enum _note_type
.macro note_type length:req, volume, fade_wave
 .byte _note_type
 .byte \length
 .ifnb \volume
  .if \fade_wave < 0
   .byte (\volume << 4) | (\fade_wave * -1) | 0b1000
  .else
   .byte (\volume << 4) | (\fade_wave)
  .endif
 .endif
.endm


.macro drum_speed length:req
 note_type \length
.endm

 enum _transpose
.macro transpose num_octaves:req, num_pitches:req
 .byte _transpose
 .byte (\num_octaves << 4) | (\num_pitches)
.endm

 enum _tempo
.macro tempo tempo:req
 .byte _tempo
 .2byte \tempo
.endm

 enum _duty_cycle
.macro duty_cycle cycle
 .byte _duty_cycle
 .byte \cycle
.endm

 enum _volume_envelope
.macro volume_envelope volume:req, fade_wave:req
 .byte _volume_envelope
 .if \fade_wave < 0
  .byte (\volume << 4) | (\fade_wave * -1) | 0b1000
 .else
  .byte (\volume << 4) | (\fade_wave)
 .endif
.endm

 enum _pitch_sweep
.macro pitch_sweep length:req, pitch_change:req
 .byte _pitch_sweep
 .if \pitch_change < 0
  .byte (\length << 4) | (\pitch_change * -1) | 0b1000
 .else
  .byte (\length << 4) | (\pitch_change)
 .endif
.endm

 enum _duty_cycle_pattern
.macro duty_cycle_pattern a:req, b:req, c:req, d:req
 .byte _duty_cycle_pattern
 .byte (\a << 6) | (\b << 4) | (\c << 2) | (\d << 0)
.endm

