 .endm






 .macro setfollowernpc localId:req, flags:req, script=0, battlePartner=0
 .if FALSE
  checkfollowernpc
  compare 32781, FALSE
  goto_if_ne 1f
  hidefollower
  waitmovement 0xFE
  callnative ScriptSetFollowerNPC
  .if \script == 0
   .set setScript, FALSE
  .else
   .set setScript, TRUE
  .endif
  .byte \localId
  .2byte \flags
  .byte setScript
  .2byte \battlePartner
  .4byte \script
  updatefollowingmon
  1:
 .else
  .error "setfollowernpc unavailable with FNPC_ENABLE_NPC_FOLLOWERS defined as FALSE"
 .endif
 .endm


 .macro createfollowernpc gfx:req, flags:req, script=0, battlePartner=0
