  callnative ScriptCreateFollowerNPC
  .2byte \gfx
  .2byte \flags
  .4byte \script
  .2byte \battlePartner
 .else
  .error "createfollowernpc unavailable with FNPC_ENABLE_NPC_FOLLOWERS defined as FALSE"
 .endif
 .endm


